examples.template:
MonarchButton(text = {{trigger}}, onClick = { open = true }, variant = MonarchButtonVariant.Danger)
if (open) {
    MonarchBottomSheet(onDismissRequest = { open = false }, dismissible = !verifying) {
        MonarchStepUpAuthDialog(
            onVerify = { _ ->
                // Send the credential to the server; throw if it is refused.
            },
            description = {{description}},
            methods = listOf(MonarchStepUpMethod.Password),
            onForgot = {},
            onCancel = { open = false },
            onVerified = { open = false },
            onVerifyingChange = { verifying = it },
        )
    }
}

